 chat=["P: ¿Ya has pensado qué le vas a escribir al señor Ruiz? Es el jefe de Cultura del ayuntamiento y hay que ser muy correctos. | Já pensou no que vai escrever ao senhor Ruiz? Ele é o chefe de Cultura da prefeitura e é preciso ser muito correto.",
  "Y: Lo he intentado, pero me sale demasiado informal: «Hola, Ruiz, necesito hablar contigo». | Tentei, mas sai informal demais: «Oi, Ruiz, preciso falar com você».",
  "P: ¡Ni se te ocurra! Empieza con un saludo formal: «Estimado señor Ruiz:». | Nem pense nisso! Comece com uma saudação formal: «Prezado senhor Ruiz:».",
  "Y: Vale. ¿Y cómo explico el motivo sin sonar seco? | Certo. E como explico o motivo sem soar seco?",
  "P: Así: «Le escribo para solicitarle una reunión con el fin de hablar de la subvención al periódico». | Assim: «Escrevo para lhe solicitar uma reunião a fim de falar do subsídio ao jornal».",
  "Y: Suena muy bien. ¿Y para despedirme? ¿Pongo «Un abrazo»? | Soa muito bem. E para me despedir? Ponho «Um abraço»?",
  "P: Mejor «Atentamente» o «Un cordial saludo». Y si adjuntas algo, avisa: «Adjunto el dosier del periódico». | Melhor «Atenciosamente» ou «Cordiais saudações». E se anexar algo, avise: «Anexo o dossiê do jornal».",
  "Y: Hecho. ¿Le propongo ya una fecha? | Feito. Já lhe proponho uma data?",
  "P: Propón dos, para que pueda elegir: «Quedo a su disposición el martes o el jueves». | Proponha duas, para que ele possa escolher: «Fico à sua disposição na terça ou na quinta».",
  "Y: Perfecto, lo envío ahora mismo. Gracias por la ayuda, Pablo. | Perfeito, envio agora mesmo. Obrigado pela ajuda, Pablo.",
  "P: De nada. Oye, en mi laboratorio hay una foto antigua que Javier no debería tener guardada. Mañana te la enseño, pero no hagas preguntas todavía. | De nada. Ei, no meu laboratório há uma foto antiga que Javier não deveria ter guardada. Amanhã mostro a você, mas não faça perguntas ainda."],
 tap=[("¿Quién es el señor Ruiz?","Quem é o senhor Ruiz?",["El jefe de Cultura del ayuntamiento","Un fotógrafo","El administrador del edificio"],0,0,"P: “el jefe de Cultura del ayuntamiento”"),
  ("¿Cómo propone Pablo despedirse?","Como Pablo propõe se despedir?",["Con «Un abrazo»","Con «Atentamente»","Con «Hasta luego»"],1,6,"P: “Mejor «Atentamente» o «Un cordial saludo»”"),
  ("¿Qué debe proponer Y en el correo?","O que Y deve propor no e-mail?",["Una cena","Dos fechas para la reunión","Un descuento"],1,8,"P: “Propón dos, para que pueda elegir”")],
 swap=("E-mail formal: «Le escribo para solicitarle…», «Quedo a su disposición». 🎓 DELE B2: redigir correspondência formal.",
  [("Le escribo para…",[("Le escribo para","Escrevo para"),("Me dirijo a usted para","Dirijo-me ao senhor para"),("Me pongo en contacto para","Entro em contato para")],[("solicitarle una reunión","lhe solicitar uma reunião"),("pedirle información","lhe pedir informações"),("confirmar la cita","confirmar o compromisso")],"."),
   ("Quedo a su disposición…",[("Quedo a su disposición","Fico à sua disposição"),("Le agradezco su atención","Agradeço sua atenção"),("Adjunto el documento","Anexo o documento")],[("el martes","na terça"),("para cualquier duda","para qualquer dúvida"),("con este correo","com este e-mail")],".")]),
 chat2=["Y: Estimado señor Ruiz: le escribo para solicitarle una reunión. | Prezado senhor Ruiz: escrevo para lhe solicitar uma reunião.",
  "P: Ruiz contesta rápido: «Estimado colega, podemos vernos el jueves a las diez». | Ruiz responde rápido: «Prezado colega, podemos nos ver na quinta às dez».",
  "Y: Le agradezco su respuesta. Allí estaré con el dosier completo. | Agradeço sua resposta. Estarei lá com o dossiê completo.",
  "P: Pide también que confirme por escrito, para que quede constancia. | Peça também que confirme por escrito, para ficar registrado.",
  "Y: Buena idea: «Le ruego que me lo confirme por correo». | Boa ideia: «Peço-lhe que me confirme por e-mail».",
  "P: Muy bien. Ya escribes como un profesional. | Muito bem. Você já escreve como um profissional."],
 slang=("Pablo",["✉️","#AE3EC9"],["F: Oye, tío, hay mogollón de curro con la subvención, ¿no? | Ei, cara, tem um montão de trabalho com o subsídio, né?","Y: Y que lo digas. El correo al Ruiz me ha costado un montón. | Nem me fale. O e-mail para o Ruiz me custou um montão.","F: Si quieres, puedo echar un cable con las frases formales. | Se quiser, posso dar uma mão com as frases formais.","Y: Mil gracias, me flipa tener un amigo así. | Mil obrigados, adoro ter um amigo assim.","F: Anda ya, que luego me invitas a unas cañas. | Deixa disso, depois você me paga uns chopes.","Y: Hecho, tío. Cañas y correos formales. | Combinado, cara. Chopes e e-mails formais."],
  {"mogollón":"um montão","curro":"trabalho (Espanha, gíria)","echar un cable":"dar uma mão","me flipa":"eu adoro","cañas":"chopes pequenos"},["echar un cable","me flipa"]),
