 v=[("la entrevista","a entrevista","Soa como “la en-tre-BIS-ta”.","🎙️"),("el puesto","o cargo, a vaga","Soa como “el PUES-to”.","💼"),("la trayectoria","a trajetória","Soa como “la tra-iek-TÔ-ria”.","📈"),("la motivación","a motivação","Soa como “la mo-ti-ba-THION”.","🔥"),("la fortaleza","o ponto forte","Soa como “la for-ta-LÊ-tha”.","💪"),("si me permite","se me permite","Soa como “si me per-MI-te”.","🙋")],
 chat=["P: Buenos días y muchas gracias por recibirme. Estoy muy contento de estar aquí. | Bom dia e muito obrigado por me receber. Estou muito contente de estar aqui.",
  "Y: Bienvenido, Tomás. Pase y siéntese, por favor. Cuénteme brevemente su trayectoria. | Bem-vindo, Tomás. Entre e sente-se, por favor. Conte-me brevemente sua trajetória.",
  "P: Con gusto. Estudié Periodismo en la Universidad de Chile, hice prácticas en un diario regional y escribo un blog sobre barrios de Santiago. | Com prazer. Estudei Jornalismo na Universidade do Chile, fiz estágio em um jornal regional e escrevo um blog sobre bairros de Santiago.",
  "Y: Interesante. ¿Por qué quiere trabajar en un periódico de barrio? | Interessante. Por que quer trabalhar em um jornal de bairro?",
  "P: Porque creo en el periodismo cercano. Mi trayectoria me ha preparado para este puesto y mi motivación es aprender de la gente. | Porque acredito no jornalismo próximo. Minha trajetória me preparou para este cargo e minha motivação é aprender com as pessoas.",
  "Y: ¿Cuál diría que es su mayor fortaleza? | Qual diria que é seu maior ponto forte?",
  "P: La curiosidad. Y, si me permite una debilidad, a veces me cuesta decir que no a un proyecto nuevo. | A curiosidade. E, se me permite uma fraqueza, às vezes tenho dificuldade de dizer não a um projeto novo.",
  "Y: Es una respuesta honesta. ¿Cómo se ve dentro de cinco años? | É uma resposta honesta. Como se vê daqui a cinco anos?",
  "P: Idealmente, dirigiendo un equipo pequeño, como usted ahora, y aprendiendo cada día. | Idealmente, dirigindo uma equipe pequena, como o senhor agora, e aprendendo a cada dia.",
  "Y: Muy bien. ¿Tiene alguna pregunta para nosotros? | Muito bem. Tem alguma pergunta para nós?",
  "P: Sí, una, si me permite: ¿es cierto que el periódico no tiene dinero para pagar a sus colaboradores? Me lo comentaron en la calle. | Sim, uma, se me permite: é verdade que o jornal não tem dinheiro para pagar seus colaboradores? Me comentaram na rua."],
 tap=[("¿Qué estudió Tomás?","O que Tomás estudou?",["Periodismo","Derecho","Arquitectura"],0,2,"P: “Estudié Periodismo en la Universidad de Chile”"),
  ("¿Cuál es la mayor fortaleza de Tomás?","Qual é o maior ponto forte de Tomás?",["La puntualidad","La curiosidad","El humor"],1,6,"P: “La curiosidad”"),
  ("¿Qué pregunta Tomás al final?","O que Tomás pergunta no final?",["Si hay vacaciones","Si hay café","Si el periódico no tiene dinero para pagar"],2,10,"P: “¿es cierto que el periódico no tiene dinero para pagar a sus colaboradores?”")],
 swap=("Entrevista: «Mi trayectoria me ha preparado para…», «Si me permite…». 🎓 DELE B2: falar de experiência e motivação.",
  [("Mi trayectoria me ha preparado para…",[("Mi trayectoria me ha preparado para","Minha trajetória me preparou para"),("Mi experiencia me permite","Minha experiência me permite"),("Mi formación me capacita para","Minha formação me capacita para")],[("este puesto","este cargo"),("trabajar en equipo","trabalhar em equipe"),("afrontar nuevos retos","enfrentar novos desafios")],"."),
   ("Si me permite…",[("Si me permite,","Se me permite,"),("Si no le importa,","Se não se importa,"),("Con su permiso,","Com sua licença,")],[("tengo una pregunta","tenho uma pergunta"),("quisiera añadir algo","gostaria de acrescentar algo"),("me gustaría preguntar","gostaria de perguntar")],".")]),
 chat2=["Y: Buenas tardes. Me gustaría presentarme: soy periodista y busco este puesto. | Boa tarde. Gostaria de me apresentar: sou jornalista e busco este cargo.",
  "P: Encantado. ¿Qué experiencia tiene? | Prazer. Que experiência tem?",
  "Y: Tres años en prensa local y un año en radio. | Três anos em imprensa local e um ano em rádio.",
  "P: ¿Y por qué quiere dejar su puesto actual? | E por que quer deixar seu cargo atual?",
  "Y: Busco un nuevo reto y más responsabilidad. | Busco um novo desafio e mais responsabilidade.",
  "P: Muy bien. Le llamaremos en una semana. | Muito bem. Ligaremos em uma semana."],
 slang=("Tomás",["👔","#AE3EC9"],["F: Oye, cachai que me dio un nervio terrible en la entrevista? | Ei, sabe que me deu um nervoso terrível na entrevista?","Y: Pero te fue bacán, po. | Mas você foi bem, né.","F: Sí, al tiro me relajé cuando hablamos de periodismo. | Sim, na hora me relaxei quando falamos de jornalismo.","Y: Qué bueno. Un trabajo fome no es para ti. | Que bom. Um trabalho chato não é para você.","F: Para nada, quiero una pega con sentido. | De jeito nenhum, quero um trabalho com sentido.","Y: La tendrás, ya verás. | Você vai ter, vai ver."],
  {"cachai":"entende? (Chile)","bacán":"legal, bacana","al tiro":"na hora, já (Chile)","fome":"chato, sem graça (Chile)","pega":"trabalho, emprego (Chile)"},["cachai","al tiro"]),
